46: function resizeCanvas() {
47:   const ratio = window.devicePixelRatio || 1;
48:   const shell = document.getElementById('game-shell');
49:   const rect = shell.getBoundingClientRect();
50:   canvas.width = Math.round(rect.width * ratio);
51:   canvas.height = Math.round(rect.height * ratio);
52:   ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
53:   world.width = rect.width;
54:   world.height = rect.height;
55:   if (world.player) {
56:     world.player.x = clamp(world.player.x, 0, world.width);
57:     world.player.y = clamp(world.player.y, 0, world.height);
58:   }
59: }
