61: function createPlayer() {
62:   return {
63:     x: world.width / 2,
64:     y: world.height / 2,
65:     radius: 18,
66:     speed: 220,
67:     hp: 100,
68:     maxHp: 100,
69:     fireCooldown: 0,
70:     angle: 0,
71:     weaponLevel: 1,
72:     gunFlash: 0,
73:     invuln: 0,
74:   };
75: }
