77: function spawnWave() {
78:   const count = 5 + world.wave * 2;
79:   world.spawnTimer = 0;
80:   for (let i = 0; i < count; i += 1) {
81:     const side = Math.floor(Math.random() * 4);
82:     const margin = 60;
83:     let x = 0;
84:     let y = 0;
85:     if (side === 0) { x = Math.random() * world.width; y = -margin; }
86:     if (side === 1) { x = world.width + margin; y = Math.random() * world.height; }
87:     if (side === 2) { x = Math.random() * world.width; y = world.height + margin; }
88:     if (side === 3) { x = -margin; y = Math.random() * world.height; }
89:     world.zombies.push(createZombie(x, y));
90:   }
91: }
92: 
93: function createZombie(x, y) {
94:   const levelBoost = 1 + (world.wave - 1) * 0.15;
95:   return {
96:     x,
97:     y,
98:     radius: 18,
99:     speed: 36 + Math.random() * 20 * levelBoost,
100:     hp: 32 + world.wave * 4,
101:     maxHp: 32 + world.wave * 4,
102:     damage: 10 + world.wave * 1.2,
103:     color: 'hsl(' + (120 + Math.random() * 24) + ', 55%, 46%)',
104:     eyeFluid: Math.random() * 0.8 + 0.4,
105:     hitFlash: 0,
106:   };
107: }
108: 
109: function createBullet(x, y, angle) {
110:   world.bullets.push({
111:     x,
112:     y,
113:     vx: Math.cos(angle) * 520,
114:     vy: Math.sin(angle) * 520,
115:     radius: 4,
116:     life: 1.1,
117:     damage: 20 + (world.player.weaponLevel - 1) * 8,
118:     color: '#f8d67d',
119:   });
120: }
121: 
122: function createExplosion(x, y, radius, color = '#ffbb33') {
123:   world.explosions.push({ x, y, radius, maxRadius: radius, color, life: 0.45, alpha: 1 });
124:   for (let i = 0; i < 18; i += 1) {
125:     world.particles.push({
126:       x,
127:       y,
128:       vx: (Math.random() - 0.5) * 200,
129:       vy: (Math.random() - 0.5) * 200,
130:       radius: 2 + Math.random() * 3,
131:       life: 0.8 + Math.random() * 0.6,
132:       color,
133:     });
134:   }
135: }
136: 
137: function addPickup(x, y, type = 'ammo') {
138:   world.pickups.push({
139:     x,
140:     y,
141:     radius: 10,
142:     type,
143:     bob: Math.random() * Math.PI * 2,
144:   });
145: }
