147: function createCar(x, y) {
148:   world.cars.push({
149:     x,
150:     y,
151:     radius: 24,
152:     hp: 80,
153:     angle: Math.random() * Math.PI * 2,
154:     charge: 0,
155:   });
156: }
157: 
158: function maybeSpawnCars() {
159:   if (world.cars.length > 4 || Math.random() > 0.02) return;
160:   const side = Math.floor(Math.random() * 4);
161:   let x = 0;
162:   let y = 0;
163:   if (side === 0) { x = Math.random() * world.width; y = -50; }
164:   if (side === 1) { x = world.width + 50; y = Math.random() * world.height; }
165:   if (side === 2) { x = Math.random() * world.width; y = world.height + 50; }
166:   if (side === 3) { x = -50; y = Math.random() * world.height; }
167:   createCar(x, y);
168: }
