170: function resetGame() {
171:   world.running = true;
172:   world.gameOver = false;
173:   world.score = 0;
174:   world.wave = 1;
175:   world.zombies = [];
176:   world.bullets = [];
177:   world.loot = [];
178:   world.pickups = [];
179:   world.explosions = [];
180:   world.particles = [];
181:   world.cars = [];
182:   world.player = createPlayer();
183:   hud.status.textContent = 'Survive the night';
184:   hud.waveValue.textContent = String(world.wave);
185:   hud.scoreValue.textContent = '0';
186:   spawnWave();
187: }
