194: function updatePlayer(dt) {
195:   const player = world.player;
196:   let dx = 0;
197:   let dy = 0;
198: 
199:   if (input.keys.has('w') || input.keys.has('arrowup')) dy -= 1;
200:   if (input.keys.has('s') || input.keys.has('arrowdown')) dy += 1;
201:   if (input.keys.has('a') || input.keys.has('arrowleft')) dx -= 1;
202:   if (input.keys.has('d') || input.keys.has('arrowright')) dx += 1;
203: 
204:   if (input.touchStick.active) {
205:     dx += input.touchStick.x;
206:     dy += input.touchStick.y;
207:   }
208: 
209:   const length = Math.hypot(dx, dy) || 1;
210:   const moveX = (dx / length) * player.speed * dt;
211:   const moveY = (dy / length) * player.speed * dt;
212:   player.x = clamp(player.x + moveX, 20, world.width - 20);
213:   player.y = clamp(player.y + moveY, 20, world.height - 20);
214: 
215:   const pointerX = input.pointer.x;
216:   const pointerY = input.pointer.y;
217:   player.angle = Math.atan2(pointerY - player.y, pointerX - player.x);
218: 
219:   player.fireCooldown -= dt;
220:   if ((input.fire || input.pointer.down) && player.fireCooldown <= 0) {
221:     const shotSpread = 0.08 * player.weaponLevel;
222:     const spread = (Math.random() - 0.5) * shotSpread;
223:     const angle = player.angle + spread;
224:     createBullet(player.x + Math.cos(angle) * 26, player.y + Math.sin(angle) * 26, angle);
225:     player.fireCooldown = 0.15;
226:     player.gunFlash = 0.08;
227:   }
228: 
229:   if (input.bomb && player.weaponLevel >= 2) {
230:     input.bomb = false;
231:     const blastRadius = 120;
232:     for (const zombie of world.zombies) {
233:       const d = dist(player.x, player.y, zombie.x, zombie.y);
234:       if (d < blastRadius + zombie.radius) {
235:         zombie.hp -= 40;
236:       }
237:     }
238:     for (const car of world.cars) {
239:       const d = dist(player.x, player.y, car.x, car.y);
240:       if (d < blastRadius) {
241:         car.hp -= 70;
242:       }
243:     }
244:     createExplosion(player.x, player.y, blastRadius, '#ff5d73');
245:     hud.status.textContent = 'Bomb burst!';
246:   }
247: 
248:   if (player.invuln > 0) player.invuln -= dt;
249:   if (player.gunFlash > 0) player.gunFlash -= dt;
250: }
251: 
252: function resolveZombieMovement(zombie, dt) {
253:   const dx = world.player.x - zombie.x;
254:   const dy = world.player.y - zombie.y;
255:   const len = Math.hypot(dx, dy) || 1;
256:   zombie.x += (dx / len) * zombie.speed * dt;
257:   zombie.y += (dy / len) * zombie.speed * dt;
258: }
259: 
260: function updateBullets(dt) {
261:   for (let i = world.bullets.length - 1; i >= 0; i -= 1) {
262:     const bullet = world.bullets[i];
263:     bullet.x += bullet.vx * dt;
264:     bullet.y += bullet.vy * dt;
265:     bullet.life -= dt;
266: 
267:     if (bullet.life <= 0 || bullet.x < -20 || bullet.x > world.width + 20 || bullet.y < -20 || bullet.y > world.height + 20) {
268:       world.bullets.splice(i, 1);
269:       continue;
270:     }
271: 
272:     for (let j = world.zombies.length - 1; j >= 0; j -= 1) {
273:       const zombie = world.zombies[j];
274:       if (dist(bullet.x, bullet.y, zombie.x, zombie.y) < bullet.radius + zombie.radius) {
275:         zombie.hp -= bullet.damage;
276:         zombie.hitFlash = 0.08;
277:         world.bullets.splice(i, 1);
278:         if (zombie.hp <= 0) {
279:           world.score += 15;
280:           world.zombies.splice(j, 1);
281:           createExplosion(zombie.x, zombie.y, 22, '#9ae6b4');
282:           if (Math.random() < 0.28) addPickup(zombie.x, zombie.y, 'ammo');
283:           else if (Math.random() < 0.12) addPickup(zombie.x, zombie.y, 'health');
284:         }
285:         break;
286:       }
287:     }
288:   }
289: }
290: 
291: function updateCars(dt) {
292:   for (let i = world.cars.length - 1; i >= 0; i -= 1) {
293:     const car = world.cars[i];
294:     car.charge = Math.min(1, car.charge + dt * 0.2);
295:     if (car.charge > 0.9 && Math.random() < 0.03) {
296:       createExplosion(car.x, car.y, 34, '#f97316');
297:       car.hp -= 20;
298:       car.charge = 0;
299:     }
300:     const dx = world.player.x - car.x;
301:     const dy = world.player.y - car.y;
302:     const len = Math.hypot(dx, dy) || 1;
303:     car.x += (dx / len) * 18 * dt;
304:     car.y += (dy / len) * 18 * dt;
305: 
306:     if (dist(car.x, car.y, world.player.x, world.player.y) < car.radius + world.player.radius + 10) {
307:       world.player.hp -= 10 * dt;
308:     }
309: 
310:     if (car.hp <= 0) {
311:       createExplosion(car.x, car.y, 48, '#fbbf24');
312:       world.cars.splice(i, 1);
313:       world.score += 40;
314:       continue;
315:     }
316:   }
317: }
318: 
319: function updatePickups(dt) {
320:   for (let i = world.pickups.length - 1; i >= 0; i -= 1) {
321:     const item = world.pickups[i];
322:     item.bob += dt * 4;
323:     const d = dist(item.x, item.y, world.player.x, world.player.y);
324:     if (d < item.radius + world.player.radius + 6) {
325:       if (item.type === 'ammo') {
326:         world.player.weaponLevel = Math.min(5, world.player.weaponLevel + 1);
327:         hud.status.textContent = 'Weapon upgraded';
328:       }
329:       if (item.type === 'health') {
330:         world.player.hp = Math.min(world.player.maxHp, world.player.hp + 25);
331:         hud.status.textContent = 'Health refill';
332:       }
333:       world.pickups.splice(i, 1);
334:     }
335:   }
336: }
337: 
338: function updateParticles(dt) {
339:   for (let i = world.particles.length - 1; i >= 0; i -= 1) {
340:     const p = world.particles[i];
341:     p.x += p.vx * dt;
342:     p.y += p.vy * dt;
343:     p.life -= dt;
344:     if (p.life <= 0) world.particles.splice(i, 1);
345:   }
346: }
347: 
348: function updateExplosions(dt) {
349:   for (let i = world.explosions.length - 1; i >= 0; i -= 1) {
350:     const e = world.explosions[i];
351:     e.life -= dt;
352:     e.radius += 120 * dt;
353:     if (e.life <= 0) world.explosions.splice(i, 1);
354:   }
355: }
356: 
357: function updateWave(dt) {
358:   world.spawnTimer -= dt;
359:   if (world.zombies.length === 0 && world.spawnTimer <= 0) {
360:     world.wave += 1;
361:     hud.waveValue.textContent = String(world.wave);
362:     hud.status.textContent = `Wave ${world.wave}`;
363:     world.spawnTimer = 1.25;
364:     setTimeout(() => spawnWave(), 120);
365:   }
366:   if (world.zombies.length > 0 && world.spawnTimer <= -0.5) {
367:     world.spawnTimer = 0;
368:   }
369: }
370: 
371: function updateCombat(dt) {
372:   for (let i = world.zombies.length - 1; i >= 0; i -= 1) {
373:     const zombie = world.zombies[i];
374:     resolveZombieMovement(zombie, dt);
375:     if (dist(zombie.x, zombie.y, world.player.x, world.player.y) < zombie.radius + world.player.radius) {
376:       world.player.hp -= zombie.damage * dt;
377:       zombie.eyeFluid = 1;
378:       if (world.player.hp <= 0) {
379:         world.player.hp = 0;
380:         world.running = false;
381:         world.gameOver = true;
382:         hud.overlay.classList.remove('hidden');
383:         hud.status.textContent = 'You were overwhelmed';
384:         const card = hud.overlay.querySelector('.card');
385:         card.innerHTML = `
386:           <h1>Game Over</h1>
387:           <p>Wave reached: ${world.wave}</p>
388:           <p>Score: ${world.score}</p>
389:           <button id="restartButton">Play Again</button>
390:         `;
391:         const restartButton = document.getElementById('restartButton');
392:         restartButton.addEventListener('click', () => {
393:           hud.overlay.classList.add('hidden');
394:           startGame();
395:         });
396:       }
397:     }
398: 
399:     zombie.hitFlash = Math.max(0, zombie.hitFlash - dt * 2);
400:     if (zombie.hp <= 0) {
401:       world.zombies.splice(i, 1);
402:     }
403:   }
404: }
405: 
406: function updateGame(dt) {
407:   if (!world.running || world.gameOver) return;
408:   updatePlayer(dt);
409:   updateCars(dt);
410:   updateBullets(dt);
411:   updatePickups(dt);
412:   updateCombat(dt);
413:   updateParticles(dt);
414:   updateExplosions(dt);
415:   maybeSpawnCars();
416:   updateWave(dt);
417: 
418:   if (world.player.hp <= 0) {
419:     world.running = false;
420:     world.gameOver = true;
421:   }
422: 
423:   hud.healthFill.style.width = `${(world.player.hp / world.player.maxHp) * 100}%`;
424:   hud.scoreValue.textContent = String(world.score);
425: }
426: 
427: function drawBackground() {
428:   const g = ctx.createLinearGradient(0, 0, 0, world.height);
429:   g.addColorStop(0, '#12232a');
430:   g.addColorStop(1, '#05090d');
431:   ctx.fillStyle = g;
432:   ctx.fillRect(0, 0, world.width, world.height);
433: 
434:   for (let i = 0; i < 20; i += 1) {
435:     const x = (i * 67 + (performance.now() * 0.01)) % (world.width + 200) - 100;
436:     const y = (i * 97 + (performance.now() * 0.02)) % (world.height + 200) - 100;
437:     ctx.fillStyle = 'rgba(255,255,255,0.06)';
438:     ctx.fillRect(x, y, 18, 18);
439:   }
440: }
441: 
442: function drawPlayer() {
443:   const p = world.player;
444:   ctx.save();
445:   ctx.translate(p.x, p.y);
446:   ctx.rotate(p.angle);
447:   ctx.fillStyle = '#c5f1ff';
448:   ctx.fillRect(-8, -5, 24, 10);
449:   ctx.fillStyle = '#7dd3fc';
450:   ctx.fillRect(10, -3, 12, 6);
451:   if (p.gunFlash > 0) {
452:     ctx.fillStyle = 'rgba(255, 213, 80, 0.9)';
453:     ctx.fillRect(18, -2, 12, 4);
454:   }
455:   ctx.restore();
456: 
457:   ctx.beginPath();
458:   ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
459:   ctx.fillStyle = 'rgba(34,197,94,0.25)';
460:   ctx.fill();
461:   ctx.beginPath();
462:   ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
463:   ctx.strokeStyle = '#7dd3fc';
464:   ctx.lineWidth = 2;
465:   ctx.stroke();
466: }
467: 
468: function drawBullets() {
469:   for (const bullet of world.bullets) {
470:     ctx.beginPath();
471:     ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
472:     ctx.fillStyle = bullet.color;
473:     ctx.fill();
474:   }
475: }
476: 
477: function drawZombies() {
478:   for (const zombie of world.zombies) {
479:     ctx.save();
480:     ctx.translate(zombie.x, zombie.y);
481:     const glow = zombie.hitFlash > 0 ? '#fff' : zombie.color;
482:     ctx.fillStyle = glow;
483:     ctx.beginPath();
484:     ctx.arc(0, 0, zombie.radius, 0, Math.PI * 2);
485:     ctx.fill();
486: 
487:     ctx.fillStyle = '#f8fafc';
488:     ctx.beginPath();
489:     ctx.arc(-5, -6, 2.7, 0, Math.PI * 2);
490:     ctx.arc(5, -6, 2.7, 0, Math.PI * 2);
491:     ctx.fill();
492: 
493:     ctx.fillStyle = '#dbeafe';
494:     ctx.fillRect(-7, 5, 14, 3);
495:     ctx.fillStyle = '#fca5a5';
496:     if (zombie.eyeFluid > 0.5) {
497:       ctx.fillRect(-2, -10, 3, 5);
498:       ctx.fillRect(2, -10, 3, 5);
499:     }
500:     ctx.restore();
501: 
502:     const normal = zombie.hp / zombie.maxHp;
503:     ctx.fillStyle = 'rgba(0,0,0,0.35)';
504:     ctx.fillRect(zombie.x - 18, zombie.y - 30, 36, 5);
505:     ctx.fillStyle = '#34d399';
506:     ctx.fillRect(zombie.x - 18, zombie.y - 30, 36 * normal, 5);
507:   }
508: }
509: 
510: function drawCars() {
511:   for (const car of world.cars) {
512:     ctx.save();
513:     ctx.translate(car.x, car.y);
514:     ctx.rotate(car.angle);
515:     ctx.fillStyle = '#9ca3af';
516:     ctx.fillRect(-18, -10, 36, 20);
517:     ctx.fillStyle = '#111827';
518:     ctx.fillRect(-6, -12, 12, 24);
519:     ctx.fillStyle = '#fbbf24';
520:     ctx.fillRect(-12, -15, 24, 5);
521:     ctx.restore();
522:   }
523: }
524: 
525: function drawPickups() {
526:   for (const item of world.pickups) {
527:     const bob = Math.sin(item.bob) * 5;
528:     ctx.save();
529:     ctx.translate(item.x, item.y + bob);
530:     if (item.type === 'ammo') {
531:       ctx.fillStyle = '#f8d67d';
532:       ctx.fillRect(-8, -8, 16, 16);
533:       ctx.strokeStyle = '#fff';
534:       ctx.strokeRect(-8, -8, 16, 16);
535:     } else {
536:       ctx.fillStyle = '#4ade80';
537:       ctx.beginPath();
538:       ctx.arc(0, 0, 9, 0, Math.PI * 2);
539:       ctx.fill();
540:       ctx.fillStyle = '#fff';
541:       ctx.fillRect(-2, -6, 4, 12);
542:       ctx.fillRect(-6, -2, 12, 4);
543:     }
544:     ctx.restore();
545:   }
546: }
547: 
548: function drawParticles() {
549:   for (const p of world.particles) {
550:     ctx.globalAlpha = Math.max(0, p.life * 1.2);
551:     ctx.fillStyle = p.color;
552:     ctx.beginPath();
553:     ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
554:     ctx.fill();
555:   }
556:   ctx.globalAlpha = 1;
557: }
558: 
559: function drawExplosions() {
560:   for (const e of world.explosions) {
561:     ctx.beginPath();
562:     ctx.arc(e.x, e.y, e.radius, 0, Math.PI * 2);
563:     ctx.strokeStyle = `rgba(255,255,255,${e.life * 1.8})`;
564:     ctx.lineWidth = 3;
565:     ctx.stroke();
566:     ctx.beginPath();
567:     ctx.arc(e.x, e.y, e.radius * 0.6, 0, Math.PI * 2);
568:     ctx.strokeStyle = e.color.replace(')', `, ${e.life})`).replace('hsl', 'hsla');
569:     ctx.lineWidth = 2;
570:     ctx.stroke();
571:   }
572: }
573: 
574: function draw() {
575:   drawBackground();
576:   drawCars();
577:   drawPickups();
578:   drawBullets();
579:   drawZombies();
580:   drawParticles();
581:   drawExplosions();
582:   drawPlayer();
583: }
584: 
585: function tick(timestamp) {
586:   const dt = Math.min((timestamp - world.lastTime) / 1000 || 0.016, 0.035);
587:   world.lastTime = timestamp;
588:   if (world.running) updateGame(dt);
589:   draw();
590:   requestAnimationFrame(tick);
591: }
592: 
593: function setPointerPosition(clientX, clientY) {
594:   const rect = canvas.getBoundingClientRect();
595:   input.pointer.x = clientX - rect.left;
596:   input.pointer.y = clientY - rect.top;
